TARGET_FILES = [
    "lib/core/notification_service.dart",
    "lib/features/body/body_photo_screen.dart",
    "lib/features/body/body_screen.dart",
    "lib/features/health/health_screen.dart",
    "lib/features/home/home_screen.dart",
    "lib/features/nutrition/nutrition_screen.dart",
    "lib/features/onboarding/onboarding_screen.dart",
    "lib/features/paywall/paywall_screen.dart",
    "lib/features/profile/profile_screen.dart",
    "lib/features/scanner/food_photo_screen.dart",
    "lib/features/scanner/scanner_screen.dart",
    "lib/features/settings/donation_card.dart",
    "lib/features/settings/settings_screen.dart",
    "lib/features/barakah/barakah_screen.dart",
]

# Pattern: tLang(lang, 'ar', 'en', 'en', 'en', 'en', 'en')
# The fallback script used EN for all 5 non-AR/EN langs
PATTERN = re.compile(
    r"tLang\(lang,\s*'([^']+)',\s*'([^']+)',\s*'([^']+)',\s*'([^']+)',\s*'([^']+)',\s*'([^']+)'\)"
)

def escape(s):
    return s.replace("\\", "\\\\").replace("'", "\\'")

total = 0
for path in TARGET_FILES:
    if not os.path.exists(path):
        print(f"  [~] {path} not found")
        continue

    with open(path, "r", encoding="utf-8") as f:
        src = f.read()

    original = src
    count = 0

    for m in PATTERN.finditer(original):
        ar_raw = m.group(1)
        en_raw = m.group(2)
        fr_cur = m.group(3)
        tr_cur = m.group(4)
        ms_cur = m.group(5)
        id_cur = m.group(6)

        # Only replace if fr/tr/ms/id are still English fallback
        en_key = en_raw
        t = TRANSLATIONS.get(en_key)
        if not t:
            # Try with ar key
            continue

        fr_new = escape(t.get("fr", en_raw))
        tr_new = escape(t.get("tr", en_raw))
        ms_new = escape(t.get("ms", en_raw))
        id_new = escape(t.get("id", en_raw))
        ur_new = escape(t.get("ur", ar_raw))

        old = m.group(0)
        new = f"tLang(lang, '{escape(ar_raw)}', '{escape(en_raw)}', '{fr_new}', '{tr_new}', '{ms_new}', '{id_new}')"

        if old != new:
            src = src.replace(old, new, 1)
            count += 1

    if src != original:
        with open(path, "w", encoding="utf-8") as f:
            f.write(src)
        print(f"  [+] {path.split('/')[-1]}: {count} translations applied")
        total += count
    else:
        print(f"  [~] {path.split('/')[-1]}: no changes")

print(f"\n  Total: {total} strings updated with real translations")
